{{ config(materialized='table') }}

with
quarantined as (
    select
        source_record_id,
        source_gp_id,
        source_name,
        source_lei,
        source_domicile,
        source_reported_on,
        source_external_id,
        source_relationship_start_date,
        gp_source_system,
        gp_identity_key,
        gp_normalised_name,
        gp_lei,
        gp_external_id,
        violation_00,
        violation_01
    from {{ ref("investment__gp_conformed__checked") }}
),
violations as (
    select
        'source_record_id_not_null' as rule_name,
        source_record_id,
        source_gp_id,
        source_name,
        source_lei,
        source_domicile,
        source_reported_on,
        source_external_id,
        source_relationship_start_date,
        gp_source_system,
        gp_identity_key,
        gp_normalised_name,
        gp_lei,
        gp_external_id
    from quarantined
    where violation_00

    union all

    select
        'gp_identity_key_not_null' as rule_name,
        source_record_id,
        source_gp_id,
        source_name,
        source_lei,
        source_domicile,
        source_reported_on,
        source_external_id,
        source_relationship_start_date,
        gp_source_system,
        gp_identity_key,
        gp_normalised_name,
        gp_lei,
        gp_external_id
    from quarantined
    where violation_01
)

select
    rule_name,
    source_record_id,
    source_gp_id,
    source_name,
    source_lei,
    source_domicile,
    source_reported_on,
    source_external_id,
    source_relationship_start_date,
    gp_source_system,
    gp_identity_key,
    gp_normalised_name,
    gp_lei,
    gp_external_id
from violations
